from pathlib import Path
import zlib,base64,re
p=Path("web/index.html")
s=p.read_text()
block=zlib.decompress(base64.b64decode('')).decode()
a=s.index("function mat(c,em=0){")
b=s.index("const P=new Fighter")
s=s[:a]+block+s[b:]
repls={'<title>Anime Break — Art Slice 0.4</title>': '<title>Anime Break — Visual Rework 0.6</title>', 'PROCEDURAL 3D • CEL SHADING • REAL-TIME LIGHTING': 'TOON 3D • CAMERA DE ARENA • VISUAL REWORK', 'ART SLICE 0.4 • MODELOS 3D ORIGINAIS • BUILD ANDROID': 'VISUAL REWORK 0.6 • TOON 3D • CONTROLES CORRIGIDOS', 'new THREE.Vector3(f.z,0,-f.x)': 'new THREE.Vector3().crossVectors(f,new THREE.Vector3(0,1,0)).normalize()', 'new THREE.Vector3(to.z,0,-to.x)': 'new THREE.Vector3().crossVectors(to,new THREE.Vector3(0,1,0)).normalize()', 'P.root.position.addScaledVector(d,dt*(P.ult>0?4.25:3.35)*mag)': 'P.root.position.addScaledVector(d,dt*(P.ult>0?5.85:4.85)*mag)', 'Art Slice 0.4': 'Visual Rework 0.6', '.buttons{transform:scale(.88);': '.buttons{transform:scale(.82);'}
for x,y in repls.items(): s=s.replace(x,y)
s=re.sub(r"function updateCamera\(dt\)\{.*?\}function updateHUD",'function updateCamera(dt){if(playing){const sep=clamp(dist(P,E),2,13);let target;if(locked){const baseForward=dirTo(P,E);const forward=baseForward.clone().applyAxisAngle(new THREE.Vector3(0,1,0),camYaw);const right=new THREE.Vector3().crossVectors(baseForward,new THREE.Vector3(0,1,0)).normalize();const desiredDist=clamp(5.4+sep*.22,5.8,8.6)+(camDist-9.5);target=P.root.position.clone().lerp(E.root.position,.46);target.y=1.86;const desired=P.root.position.clone().addScaledVector(forward,-desiredDist).addScaledVector(right,-.85);desired.y=2.85+camPitch*3.2;camera.position.lerp(desired,1-Math.exp(-dt*10.5))}else{target=P.root.position.clone();target.y=1.75;const desiredDist=7+(camDist-9.5);const off=new THREE.Vector3(Math.sin(camYaw)*desiredDist,3+camPitch*4,Math.cos(camYaw)*desiredDist);camera.position.lerp(P.root.position.clone().add(off),1-Math.exp(-dt*8.5))}if(shake>0){camera.position.x+=(Math.random()-.5)*shake;camera.position.y+=(Math.random()-.5)*shake*.5;shake*=Math.pow(.05,dt)}camera.lookAt(target);fovKick*=Math.pow(.04,dt);camera.fov=50+fovKick;camera.updateProjectionMatrix()}else{camera.position.lerp(new THREE.Vector3(0,4.7,10.5),1-Math.exp(-dt*2));camera.lookAt(0,2,0)}}function updateHUD',s,count=1,flags=re.S)
p.write_text(s)
print("Visual Rework 0.6 applied",len(s))
